import assert from 'node:assert/strict';import {Platformer} from '../rules.js';
let g=new Platformer();for(let i=0;i<20;i++)g.update(1/60);assert(g.player.ground>=0);g.update(1/60,new Set(['Space']),new Set(['Space']));assert(g.player.vy>0);g.player.x=47;g.update(.001);assert.equal(g.level,1,'Bubbles gate the exit');for(let i=0;i<3;i++){g.found=5;g.player.x=47;g.player.y=2;g.update(.001)}assert(g.over&&g.won);g=new Platformer();Object.assign(g.player,{x:29,y:1});g.update(.001);assert.equal(g.checkpoint.x,29);g.player.y=-10;g.update(.001);assert.equal(g.lives,4);assert.equal(g.player.x,29);g.player.x=17;g.update(.001,new Set(),new Set(['KeyE']));assert(g.bridgeStopped);console.log('Super Mario 65: landing/jumping, collectible gate, all-stage completion, checkpoints, lives and bridge interaction passed.');
